import kotlin.math.abs
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * Numerical parity tests against scipy / numpy. The expected values were produced with
 * scipy.signal.butter / filtfilt / find_peaks / lfilter_zi and numpy.fft on the same inputs.
 */
class SignalParityTest {

    private fun assertClose(expected: DoubleArray, actual: DoubleArray, tol: Double, what: String) {
        assertEquals(expected.size, actual.size, "$what: length")
        for (i in expected.indices) {
            assertTrue(abs(expected[i] - actual[i]) <= tol, "$what[$i]: expected ${expected[i]} got ${actual[i]}")
        }
    }

    @Test
    fun butterworthBandpassMatchesScipy() {
        val c = Butterworth.bandpass(3, 0.5 / 50.0, 4.0 / 50.0)
        assertClose(doubleArrayOf(0.0010794898220693148,0.0,-0.0032384694662079445,0.0,0.0032384694662079445,0.0,-0.0010794898220693148), c.b, 1e-12, "b")
        assertClose(doubleArrayOf(1.0,-5.5390031075784565,12.814616286414868,-15.852598393614546,11.060956098498172,-4.127543191519711,0.6435727067106491), c.a, 1e-9, "a")
    }

    @Test
    fun lfilterZiMatchesScipy() {
        val c = Butterworth.bandpass(3, 0.5 / 50.0, 4.0 / 50.0)
        val zi = Filters.lfilterZi(c.b, c.a)
        assertClose(doubleArrayOf(-0.0010794898220693148,-0.0010794898220693148,0.0021589796441386297,0.0021589796441386297,-0.0010794898220693148,-0.0010794898220693148), zi, 1e-9, "zi")
    }

