    @Test
    fun rfftMagnitudeMatchesNumpyForOddLength() {
        val x = doubleArrayOf(-1.6829,-0.3349,0.1628,0.5862,0.7112,0.7933,-0.3487,-0.4624,0.858,-0.1913,-1.2757,-1.1333,-0.9195,0.4972,0.1424,0.6905,-0.4273,0.1585,0.6256,-0.3093,0.4568,-0.6619,-0.3631,-0.3817,-1.1958,0.487,-0.4694,0.0125,0.4807,0.4465,0.6654,-0.0985,-0.4233,-0.0797,-1.6873,-1.4471,-1.3227)
        assertClose(doubleArrayOf(7.4411999999999985,3.5288522394806296,4.093378220847652,13.30173041819849,3.6540295842221022,0.9423080064397917,4.152988233485052,4.846731056683756,2.79345509337281,3.2903146773093646,0.5163981840935162,3.3179207687362315,3.037943603364222,2.1082879157111054,3.5694158726905933,6.175890816105699,2.7441521071295063,1.082851097190062,1.5936706372974323), Fft.rfftMagnitude(x), 1e-9, "rfft")
    }

    @Test
    fun rfftPowerOfTwoMatchesDirectDft() {
        val x = DoubleArray(64) { kotlin.math.sin(it * 0.37) + 0.1 * it }
        val fast = Fft.rfftMagnitude(x)
        val bins = x.size / 2 + 1
        for (k in 0 until bins) {
            var re = 0.0; var im = 0.0
            for (n in x.indices) {
                val ang = -2.0 * Math.PI * k * n / x.size
                re += x[n] * kotlin.math.cos(ang); im += x[n] * kotlin.math.sin(ang)
            }
            assertTrue(abs(kotlin.math.hypot(re, im) - fast[k]) < 1e-9, "bin $k")
        }
    }

    @Test
    fun hanningMatchesNumpy() {
        assertClose(doubleArrayOf(0.0,0.14644660940672627,0.5,0.8535533905932737,1.0,0.8535533905932737,0.5,0.14644660940672627,0.0), Fft.hanning(9), 1e-12, "hanning")
    }

